  "criteria": {
    "definition": {
      "assessment": "sufficient",
      "reason": "联合记录明确请求身份、外部到达、依赖事件、输入身份、媒体几何、正式输出和客户端边界，并解释边际与协方差不足以恢复联合分布。规范化状态与运行事件状态分开；已选择 token、已消费位置和可见正文没有混同。",
      "evidence": [
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "`r_i=(id_i,s_i,a_i,D_i,u_i,m_i,x_i,y_i,o_i,c_i)`。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "客户端 chunk、正式选择的 token、已消费并形成 KV 的 token、解码字节与已提交字节是不同边界。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "低阶摘要用于定位变化；有限离散样本若要声称经验联合分布完全相同，应比较规范联合记录的频数，而不能仅比较均值与协方差。"
        }
      ]
    },
    "legality": {
      "assessment": "sufficient",
      "reason": "明确制品和单位相容、删失与失败记账、完整缓存身份、依赖闭包、集合隔离及恢复点条件。独立边际抽样、完整单元重采样和连续窗口重放作为不同实验选择解释。来源核对支持 GenAI-Perf 的控制入口及其限制、PagedAttention 的共享机制和 Qwen 的图像处理条件，没有将接口或目录命中当作实际状态就绪证明。",
      "evidence": [
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "缓存复用要求完整计算身份相同、状态完成、物理副本仍驻留、路由可达及恢复点合法。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "必需依赖必须在所选单元内闭合，或由明确、可验证的初始快照满足。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "独立抽取各边际可以作为零模型或压力干预，但它改变联合规律。"
        }
      ]
    },
    "algorithm": {
      "assessment": "sufficient",
      "reason": "BuildAndAuditWorkload 给出输入输出、初始化、规范化、终止拒绝分支、依赖单元筛选、抽样支持检查、副本身份重写、事件释放、独立审计与冻结条件。双回合轨迹明确完成反馈如何改变后继就绪时间，fixture 与真实闭环的数据来源也有区分。本章核心是负载构造和计账；逐层 attention 公式声明为每层每 query head 的计数，没有借模型前向黑箱声称实现完整 decoder。已修复的拒绝落入和孤立后继问题可关闭。",
      "evidence": [
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "状态置 REJECTED；记录原因到 Reject；立即继续下一条原始记录。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "每次抽取分配全局唯一 copy_id；重写请求、会话、分支及依赖端点身份。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "节点的就绪时间不早于外部释放界及每个依赖事件时间加其等待间隔。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "真实闭环模式把本次实际提交的回答和工具结果写入下一回合，再重新计算模板、长度、缓存身份与停止边界；若内容改变，不能继续使用旧 x、y 或旧复用距离。"
        }
      ]
    },
    "cost": {
      "assessment": "sufficient",
      "reason": "prefill 配对和 decode 的 y−1 消费边界推导正确，且将 y=0 的部分执行与完成 prefill 路径分开。KV 字节、padding、CPU 准备、传输关键路径、恢复与同步均有条件化说明。唯一物理对象账区分请求、目录、在途使用和交接责任，12/8/4/0 KiB 轨迹与 28 KiB·s 积分正确，预分配池没有重复相加。Qwen 图像、窗口配对、49/63 MiB 容量及暂存字节与所供结构参数相符，并明确不是硬件事务或实测时延。",
      "evidence": [
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "正式选择第一个输出不会自动计算该输出自身的 KV。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "`P_dec=Σ_(t=1)^m(x+t)=m x+m(m+1)/2`。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "请求完成只撤 A；目录淘汰只撤 C；设备操作完成才撤对应 R/W。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "t 用秒时，I 的单位是 byte·s，`I/(t1−t0)` 才是平均驻留字节。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "通信、复制和计算若重叠，应根据依赖关键路径估时；未重叠的传输、恢复、同步和排队仍需计入。"
        }
      ]
    },
    "adaptation": {
      "assessment": "sufficient",
      "reason": "按模型制品、依赖与生成内容、缓存协议、批形成、媒体几何和取消条件分别说明可保留证据、必须重算的对象及旧结论失效条件。明确会话重采样不保留全局复用距离，以及热点排队可能反转缓存收益，能够支持条件改变后的重新选择。",
      "evidence": [
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "复制单元保留内部依赖规则，不保证保留原全局时间相关性。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "调整分辨率、crop 或抽帧规则后，应重新计算受影响输入和身份。"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "热点消失、复用变稀、缓存保留时间增大或远端排队超过省下的计算时，应放弃相应缓存性能结论。"
        }
      ]
    },
    "diagnosis": {
      "assessment": "sufficient",
      "reason": "针对缓存提速、平均长度相同但尾部变化、多轮异常提速、首输出重复计账、结束后驻留和视觉几何变化提出竞争解释、受控干预和撤回条件。指定检查的主要机制具有独立参考或明确不变量及可检测负对照，实际执行证据与脚本身份一致；没有将 CPU 模型推广成 GPU 或 Agent 效果证明。",
      "evidence": [
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "固定请求群体和停止合同，只改变缓存容量，记录命中位置、重算 query、排队和驻留；若计算未减少，撤回少算解释"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "分别撤请求、目录和最后读者，比较唯一存活对象与整个池；只在责任全撤后仍无法解释的对象才支持泄漏判断"
        },
        {
          "path": "knowledge/workloads/input-distribution.md",
          "quote": "局部模型通过后仍须在目标制品、事件采集和硬件上验证相应主张；反证先定位单位、身份、事件与分母，再修正实现或缩小结论范围。"
        }
      ]
    }
  },
